    <title>Terms Consent Form</title>
    <style>
      :root {
        color-scheme: light;
        --color-bg: #f6f8fb;
        --color-surface: #ffffff;
        --color-text: #172033;
        --color-muted: #5d6b82;
        --color-border: #c9d3e2;
        --color-primary: #2457d6;
        --color-primary-hover: #1b45af;
        --color-primary-active: #16398f;
        --color-success: #176d3b;
        --color-error: #b42318;
        --shadow-card: 0 24px 70px #d8e0ed;
        --radius-lg: 24px;
        --radius-md: 14px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-height: 100%;
      }

      body {
        min-height: 100vh;
        margin: 0;
        color: var(--color-text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        background:
          radial-gradient(circle at top left, #dce8ff 0, transparent 34rem),
          linear-gradient(135deg, #f8fbff 0%, var(--color-bg) 100%);
      }

      a {
        color: var(--color-primary);
        font-weight: 700;
        text-underline-offset: 0.18em;
      }

      a:hover {
        color: var(--color-primary-hover);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.65rem 1rem;
        color: var(--color-surface);
        background: var(--color-text);
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--color-primary);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      main {
        width: min(100%, 32rem);
      }

      .card {
        overflow-wrap: anywhere;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        padding: clamp(1.25rem, 5vw, 2.5rem);
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--color-primary);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.25rem);
        line-height: 1;
        letter-spacing: -0.055em;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: var(--color-muted);
        font-size: 1.05rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        gap: 0.35rem 0.85rem;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-md);
        padding: 1rem;
        background: #fbfdff;
      }

      .form-field:focus-within {
        border-color: var(--color-primary);
        box-shadow: 0 0 0 4px #d8e4ff;
      }

      input[type="checkbox"] {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0.1rem 0 0;
        accent-color: var(--color-primary);
        cursor: pointer;
      }

      input[type="checkbox"]:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #d8e4ff, 0 0 0 6px var(--color-primary);
      }

      label {
        font-weight: 800;
        cursor: pointer;
      }

      .required-note {
        color: var(--color-error);
        font-weight: 800;
      }

      .helper-text {
        grid-column: 2;
        margin: 0;
        color: var(--color-muted);
        font-size: 0.95rem;
      }

      button {
        min-height: 3rem;
        border: 0;
        border-radius: var(--radius-md);
        padding: 0.85rem 1.1rem;
        color: #ffffff;
        background: var(--color-primary);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition: background-color 160ms ease, transform 160ms ease;
      }

      button:hover {
        background: var(--color-primary-hover);
      }

      button:active {
        transform: translateY(1px);
        background: var(--color-primary-active);
      }

      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #d8e4ff, 0 0 0 6px var(--color-primary);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        font-weight: 700;
      }

      .status-message[data-state="success"] {
        color: var(--color-success);
      }

      .status-message[data-state="error"] {
        color: var(--color-error);
      }

      @media (max-width: 22rem) {
        .page-shell {
          padding-inline: 0.75rem;
        }

        .form-field {
          gap: 0.35rem 0.65rem;
          padding: 0.85rem;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field {
          border-color: CanvasText;
          background: Canvas;
          box-shadow: none;
        }

        .form-field:focus-within,
        .skip-link:focus,
        input[type="checkbox"]:focus-visible,
        button:focus-visible {
          outline: 3px solid ButtonBorder;
          box-shadow: none;
        }

        button {
          border: 1px solid ButtonBorder;
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <div class="page-shell">
      <main id="main-content">
        <section class="card" aria-labelledby="page-title">
          <p class="eyebrow">Account setup</p>
          <h1 id="page-title">Review your consent</h1>
          <p class="intro">
            Confirm that you agree to the terms before continuing.
          </p>

          <form id="consent-form" novalidate>
            <div class="form-field">
              <input
                type="checkbox"
                id="terms"
                name="terms"
                required
                aria-describedby="terms-helper terms-error"
              >
              <label for="terms">
                I agree to the terms of use
                <span class="required-note" aria-hidden="true">*</span>
              </label>
              <p class="helper-text" id="terms-helper">
                Required to create or continue using your account.
              </p>
            </div>

            <p
              class="status-message"
              id="terms-error"
              data-state=""
              aria-live="polite"
            ></p>

            <button type="submit">Submit consent</button>
          </form>
        </section>
      </main>
    </div>

    <script>
      const form = document.querySelector("#consent-form");
      const terms = document.querySelector("#terms");
      const message = document.querySelector("#terms-error");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!terms.checked) {
          terms.setAttribute("aria-invalid", "true");
          message.dataset.state = "error";
          message.textContent = "Please agree to the terms of use before submitting.";
          terms.focus();
          return;
        }

        terms.removeAttribute("aria-invalid");
        message.dataset.state = "success";
        message.textContent = "Thanks. Your consent has been recorded.";
      });

      terms.addEventListener("change", () => {
        if (terms.checked) {
          terms.removeAttribute("aria-invalid");
          message.dataset.state = "";
          message.textContent = "";
        }
      });
    </script>
  </body>
</html>
